arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1943_03.json') as f:
    data = json.load(f)

# Search for High-Grade Corporate in the data
def search(obj, key='high-grade corporate'):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if key in k.lower():
                print(f'Key: {k}, Value: {v}')
            search(v, key)
    elif isinstance(obj, list):
        for item in obj:
            search(item, key)

search(data)
"
